    AND e.name = v.name
);

-- 3) Canonical Reading exercise (Custom) — one per room if absent.
INSERT INTO public.exercises (
  room_id,
  name,
  points,
  icon,
  category,
  supports_weight,
  weight_threshold,
  weight_multiplier,
  created_by,
  count_unit,
  time_points_mode,
  uses_time,
  timer_ui
)
SELECT
  r.id,
  'Reading a Page(of words)',
  0.5::double precision,
  '📖',
  'Custom',
  false::boolean,
  null::double precision,
  null::double precision,
  coalesce(r.admin_id::text, 'system'),
  'reps',
  null::text,
  false::boolean,
  false::boolean
FROM public.rooms AS r
WHERE NOT EXISTS (
  SELECT 1
  FROM public.exercises AS e
  WHERE e.room_id = r.id
    AND (
      e.id = 'ac8d174d-b074-4bc5-bf54-62968e9ffb8f'::uuid
      OR e.name = 'Reading a Page(of words)'
    )
);

